import{_ as e,o as a,c as s,a2 as i}from"./chunks/framework.Crpw6aS5.js";const n="/assets/og-preview.CjKrqua8.png",k=JSON.parse(`{"title":"Enhancing RAG with Contextual Retrieval (Claude Cookbook)","description":"Imported notes from Anthropic's Claude Cookbook — contextual embeddings, hybrid BM25 search, and reranking to improve RAG retrieval.","frontmatter":{"title":"Enhancing RAG with Contextual Retrieval (Claude Cookbook)","description":"Imported notes from Anthropic's Claude Cookbook — contextual embeddings, hybrid BM25 search, and reranking to improve RAG retrieval."},"headers":[],"relativePath":"misc/artificial-intelligence/platform-claude-contextual-embeddings-guide.md","filePath":"misc/artificial-intelligence/platform-claude-contextual-embeddings-guide.md"}`),o={name:"misc/artificial-intelligence/platform-claude-contextual-embeddings-guide.md"};function r(d,t,l,c,h,p){return a(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="enhancing-rag-with-contextual-retrieval" tabindex="-1">Enhancing RAG with Contextual Retrieval <a class="header-anchor" href="#enhancing-rag-with-contextual-retrieval" aria-label="Permalink to &quot;Enhancing RAG with Contextual Retrieval&quot;">​</a></h1><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><ul><li>Type: webpage</li><li>Origin: <a href="https://platform.claude.com/cookbook/capabilities-contextual-embeddings-guide" target="_blank" rel="noreferrer">https://platform.claude.com/cookbook/capabilities-contextual-embeddings-guide</a></li><li>Imported: 2025-08-30</li><li>Related: <a href="https://www.anthropic.com/news/contextual-retrieval" target="_blank" rel="noreferrer">Contextual Retrieval blog post</a></li><li>GitHub: <a href="https://github.com/anthropics/claude-cookbooks/tree/main/capabilities/contextual-embeddings" target="_blank" rel="noreferrer">anthropics/claude-cookbooks — capabilities/contextual-embeddings</a></li><li>Images: 1 preview image saved under <code>./assets/platform-claude-contextual-embeddings-guide/</code></li></ul><p><img src="'+n+`" alt="Contextual embeddings — Claude Cookbook preview"></p><p>Interactive Python cookbook demonstrating how to improve RAG retrieval with contextual embeddings, hybrid BM25 search, and reranking. Uses a dataset of 9 codebases (248 evaluation queries) and measures performance with Pass@k.</p><h2 id="content" tabindex="-1">Content <a class="header-anchor" href="#content" aria-label="Permalink to &quot;Content&quot;">​</a></h2><h3 id="what-problem-does-this-solve" tabindex="-1">What problem does this solve? <a class="header-anchor" href="#what-problem-does-this-solve" aria-label="Permalink to &quot;What problem does this solve?&quot;">​</a></h3><p>In traditional RAG, documents are split into chunks for efficient retrieval. Individual chunks often lack sufficient context when embedded in isolation — a function definition without its module context, for example.</p><p><strong>Contextual Embeddings</strong> add relevant document-level context to each chunk before embedding. Anthropic reports this reduced top-20-chunk retrieval failure rate by <strong>35%</strong> averaged across tested data sources. The same chunk-specific context can also power <strong>Contextual BM25</strong> hybrid search.</p><h3 id="evaluation-setup" tabindex="-1">Evaluation setup <a class="header-anchor" href="#evaluation-setup" aria-label="Permalink to &quot;Evaluation setup&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Detail</th></tr></thead><tbody><tr><td>Dataset</td><td>9 pre-chunked codebases (basic character splitting)</td></tr><tr><td>Queries</td><td>248, each with a &quot;golden chunk&quot;</td></tr><tr><td>Metric</td><td><strong>Pass@k</strong> — whether the golden chunk appears in the top k retrieved results</td></tr><tr><td>Embedding model</td><td>Voyage AI (<code>voyage-2</code>)</td></tr><tr><td>Context generation</td><td>Claude Haiku 4.5</td></tr></tbody></table><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><p><strong>Skills:</strong> Intermediate Python, basic RAG concepts, familiarity with vector databases and embeddings.</p><p><strong>System:</strong> Python 3.8+, Docker (optional, for BM25/Elasticsearch), 4GB+ RAM, ~5–10 GB disk.</p><p><strong>API keys:</strong> <code>ANTHROPIC_API_KEY</code>, <code>VOYAGE_API_KEY</code>, <code>COHERE_API_KEY</code> (for reranking).</p><p><strong>Time/cost:</strong> ~30–45 minutes to run; ~$5–10 API cost for the full dataset.</p><p><strong>Libraries:</strong> <code>anthropic</code>, <code>voyageai</code>, <code>cohere</code>, <code>elasticsearch</code>, <code>pandas</code>, <code>numpy</code>, <code>matplotlib</code>, <code>scikit-learn</code>.</p><h3 id="pipeline-overview" tabindex="-1">Pipeline overview <a class="header-anchor" href="#pipeline-overview" aria-label="Permalink to &quot;Pipeline overview&quot;">​</a></h3><ol><li><strong>Basic RAG</strong> — embed raw chunks with Voyage AI, store in an in-memory vector DB (pickle-serialized), establish baseline Pass@k.</li><li><strong>Contextual Embeddings</strong> — use Claude to generate a short &quot;situating&quot; context for each chunk, prepend it before embedding.</li><li><strong>Contextual BM25</strong> — index both raw chunk content and contextual descriptions in Elasticsearch; fuse with semantic search via Reciprocal Rank Fusion.</li><li><strong>Reranking</strong> — use Cohere <code>rerank-english-v3.0</code> on top of hybrid results for final relevance scoring.</li></ol><h3 id="basic-rag-baseline" tabindex="-1">Basic RAG baseline <a class="header-anchor" href="#basic-rag-baseline" aria-label="Permalink to &quot;Basic RAG baseline&quot;">​</a></h3><p>The <code>VectorDB</code> class handles embedding generation (Voyage AI, batch size 128), disk caching (avoids re-embedding), and cosine similarity search. For production, swap in a hosted vector database while keeping the same interface.</p><p><strong>Baseline results:</strong></p><table tabindex="0"><thead><tr><th>Metric</th><th>Pass Rate</th></tr></thead><tbody><tr><td>Pass@5</td><td>80.92%</td></tr><tr><td>Pass@10</td><td>87.15%</td></tr><tr><td>Pass@20</td><td>90.06%</td></tr></tbody></table><h3 id="contextual-embeddings" tabindex="-1">Contextual Embeddings <a class="header-anchor" href="#contextual-embeddings" aria-label="Permalink to &quot;Contextual Embeddings&quot;">​</a></h3><p>For each chunk, pass the full source document and the chunk to Claude. Claude generates a concise explanation of what the chunk contains and where it fits in the document. This context is prepended before embedding.</p><p><strong>Core prompt pattern:</strong></p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DOCUMENT_CONTEXT_PROMPT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;document&gt;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{doc_content}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;/document&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">CHUNK_CONTEXT_PROMPT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Here is the chunk we want to situate within the whole document</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;chunk&gt;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{chunk_content}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;/chunk&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Please give a short succinct context to situate this chunk within the overall document</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">for the purposes of improving search retrieval of the chunk.</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Answer only with the succinct context and nothing else.</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;&quot;</span></span></code></pre></div><p>Use <code>cache_control: {&quot;type&quot;: &quot;ephemeral&quot;}</code> on the document portion so prompt caching applies when processing chunks from the same document sequentially.</p><p><strong>Cost and latency:</strong></p><ul><li>Contextualization is a <strong>one-time ingestion cost</strong>, not per-query (unlike HyDE).</li><li>Prompt caching: first chunk writes the full document to cache; subsequent chunks read from cache (~90% discount). Cache lasts 5 minutes.</li><li>Example cost: ~$1.02 per million document tokens (800-token chunks, 8k-token documents, 100 tokens of generated context).</li><li>On the 737-chunk dataset, caching reduced a ~$15 ingestion job to ~$3.</li><li>Watch for embedding model token limits — truncated contextualized chunks can hurt performance.</li></ul><p><strong>Contextual Embeddings results:</strong></p><table tabindex="0"><thead><tr><th>Metric</th><th>Pass Rate</th></tr></thead><tbody><tr><td>Pass@5</td><td>88.12%</td></tr><tr><td>Pass@10</td><td>92.34%</td></tr><tr><td>Pass@20</td><td>94.29%</td></tr></tbody></table><p>Improvement is most pronounced at Pass@5, suggesting contextualized chunks rank higher when relevant.</p><h3 id="contextual-bm25-hybrid-search" tabindex="-1">Contextual BM25: Hybrid Search <a class="header-anchor" href="#contextual-bm25-hybrid-search" aria-label="Permalink to &quot;Contextual BM25: Hybrid Search&quot;">​</a></h3><p>Combines semantic search (conceptual similarity) with BM25 (exact keyword/terminology matching) using <strong>Reciprocal Rank Fusion</strong>:</p><ol><li>Retrieve top 150 candidates from both semantic search and BM25.</li><li>Fuse rankings with weighted RRF (default: 80% semantic, 20% BM25 — tunable).</li><li>Return top-k results.</li></ol><p>BM25 indexes both <code>content</code> (original chunk) and <code>contextualized_content</code> (generated context).</p><p><strong>Elasticsearch setup (Docker):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> elasticsearch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 9200:9200</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 9300:9300</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;discovery.type=single-node&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;xpack.security.enabled=false&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  elasticsearch:9.2.0</span></span></code></pre></div><p><strong>Hybrid search results:</strong></p><table tabindex="0"><thead><tr><th>Metric</th><th>Pass Rate</th></tr></thead><tbody><tr><td>Pass@5</td><td>86.43%</td></tr><tr><td>Pass@10</td><td>93.21%</td></tr><tr><td>Pass@20</td><td>94.99%</td></tr></tbody></table><h3 id="reranking" tabindex="-1">Reranking <a class="header-anchor" href="#reranking" aria-label="Permalink to &quot;Reranking&quot;">​</a></h3><p>Retrieve top <code>k * 10</code> semantic results, then rerank with Cohere <code>rerank-english-v3.0</code>. Documents are passed as <code>original_content + contextualized_content</code>.</p><p><strong>Reranking results:</strong></p><table tabindex="0"><thead><tr><th>Metric</th><th>Pass Rate</th></tr></thead><tbody><tr><td>Pass@5</td><td>92.15%</td></tr><tr><td>Pass@10</td><td>95.26%</td></tr><tr><td>Pass@20</td><td>97.45%</td></tr></tbody></table><h3 id="cumulative-performance-comparison" tabindex="-1">Cumulative performance comparison <a class="header-anchor" href="#cumulative-performance-comparison" aria-label="Permalink to &quot;Cumulative performance comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Approach</th><th>Pass@5</th><th>Pass@10</th><th>Pass@20</th></tr></thead><tbody><tr><td>Baseline RAG</td><td>80.92%</td><td>87.15%</td><td>90.06%</td></tr><tr><td>+ Contextual Embeddings</td><td>88.12%</td><td>92.34%</td><td>94.29%</td></tr><tr><td>+ Hybrid Search (BM25)</td><td>86.43%</td><td>93.21%</td><td>94.99%</td></tr><tr><td>+ Reranking</td><td>92.15%</td><td>95.26%</td><td>97.45%</td></tr></tbody></table><p>Starting from 87% Pass@10 baseline, the full pipeline reaches <strong>95.26%</strong> — a 47% reduction in retrieval failures (12.85% → 4.74%).</p><h3 id="trade-offs-and-recommendations" tabindex="-1">Trade-offs and recommendations <a class="header-anchor" href="#trade-offs-and-recommendations" aria-label="Permalink to &quot;Trade-offs and recommendations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Technique</th><th>Cost profile</th><th>When to use</th></tr></thead><tbody><tr><td>Contextual embeddings</td><td>One-time ingestion (~$3 for this dataset with caching)</td><td>Best performance-to-cost ratio; 92% Pass@10 with no per-query cost</td></tr><tr><td>Hybrid search (BM25)</td><td>Elasticsearch infrastructure + maintenance</td><td>Strong performance without per-query API costs (93% Pass@10)</td></tr><tr><td>Reranking</td><td>+100–200ms latency, ~$0.002/query</td><td>Maximum accuracy when latency and cost are acceptable (95% Pass@10)</td></tr></tbody></table><p><strong>Platform notes:</strong></p><ul><li>Prompt caching is available on Anthropic&#39;s first-party API; coming to AWS Bedrock and GCP Vertex.</li><li>AWS Bedrock users can deploy a Lambda from <code>contextual-rag-lambda-function/lambda_function.py</code> as a custom chunking option on a Knowledge Base.</li><li>GCP users can follow a similar pattern with Cloud Run.</li></ul><h3 id="key-code-classes" tabindex="-1">Key code classes <a class="header-anchor" href="#key-code-classes" aria-label="Permalink to &quot;Key code classes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Class</th><th>Role</th></tr></thead><tbody><tr><td><code>VectorDB</code></td><td>Basic embedding storage and cosine similarity search</td></tr><tr><td><code>ContextualVectorDB</code></td><td>Adds Claude contextualization at ingestion; parallel processing via ThreadPoolExecutor</td></tr><tr><td><code>ElasticsearchBM25</code></td><td>Indexes chunks + contextual descriptions for keyword search</td></tr><tr><td><code>retrieve_advanced</code></td><td>Hybrid retrieval with weighted Reciprocal Rank Fusion</td></tr><tr><td><code>evaluate_db_rerank</code></td><td>Full pipeline evaluation with Cohere reranking</td></tr></tbody></table><p>Data files referenced in the cookbook: <code>data/codebase_chunks.json</code>, <code>data/evaluation_set.jsonl</code>.</p><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ul><li>Contextual embeddings solve the &quot;isolated chunk&quot; problem by situating each chunk within its source document before embedding — the largest single improvement (+5–7 percentage points at Pass@10).</li><li>Prompt caching makes contextualization practical at scale: process chunks document-by-document to maximize cache hits and cut ingestion cost by ~80%.</li><li>Hybrid search (semantic + Contextual BM25) catches keyword-specific queries that pure embeddings miss.</li><li>Reranking pushes Pass@10 to 95%+, but adds per-query latency and API cost.</li><li>For most production RAG systems, contextual embeddings alone offer the best performance-to-cost ratio.</li><li>These techniques apply beyond codebases — internal knowledge bases, financial/legal content, educational material, and more.</li></ul>`,57)])])}const g=e(o,[["render",r]]);export{k as __pageData,g as default};
